import manifest from "@/lib/images.gen.json";

// Variants and metadata are generated by scripts/optimize-images.mjs from src/assets/*.jpg.
export type ImageName = keyof typeof manifest.images;

type ImageMeta = { width: number; height: number; widths: number[]; fallback: number };
export const IMAGES: Record<ImageName, ImageMeta> = manifest.images;

/** AVIF `srcset` with every generated width of the image. */
export function srcSet(name: ImageName) {
  return IMAGES[name].widths.map((w) => `/img/${name}-${w}.avif ${w}w`).join(", ");
}

export function isLandscape(name: ImageName) {
  return IMAGES[name].width > IMAGES[name].height;
}

/** `<link rel="preload">` for an above-the-fold image, to put in a route's head(). */
export function imagePreload(name: ImageName, sizes: string) {
  return {
    rel: "preload",
    as: "image",
    type: "image/avif",
    imageSrcSet: srcSet(name),
    imageSizes: sizes,
    fetchPriority: "high",
  } as const;
}
